'use client'

import { useRouter } from 'next/navigation'
import type { EventApi } from '@fullcalendar/core'
import { Link2 } from 'lucide-react'
import { cn } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type BookingStatus = Database['public']['Tables']['bookings']['Row']['status']

const STATUS_DOT_CLASSES: Partial<Record<BookingStatus, string>> = {
  in_progress: 'bg-[var(--color-status-in-progress)] animate-pulse',
  completed: 'bg-[var(--color-status-completed)]',
  cancelled: 'bg-[var(--color-status-cancelled)]',
  no_show: 'bg-[var(--color-status-no-show)]',
}

interface AppointmentCardProps {
  event: EventApi
}

export function AppointmentCard({ event }: AppointmentCardProps) {
  const router = useRouter()
  const status = event.extendedProps.status as BookingStatus
  const projectId = event.extendedProps.projectId as string | null | undefined
  const sessionNumber = event.extendedProps.sessionNumber as number | null | undefined
  const projectName = event.extendedProps.projectName as string | null | undefined
  const depositCents = event.extendedProps.depositCents as number
  const depositPaid = event.extendedProps.depositPaid as boolean

  const startTime = event.start
    ? event.start.toLocaleTimeString('en-US', {
        hour: 'numeric',
        minute: '2-digit',
        hour12: true,
      })
    : ''

  const dotClass = STATUS_DOT_CLASSES[status]
  const isCancelled = status === 'cancelled'

  // Deposit dot logic: only show when deposit is required (cents > 0)
  const showDepositDot = depositCents > 0
  const depositDotTitle = depositPaid ? 'Deposit paid' : 'Deposit pending'

  return (
    <div className="relative flex h-full flex-col overflow-hidden px-1.5 py-0.5">
      <div className="flex items-center justify-between gap-1">
        <span
          className={cn(
            'text-[11px] font-medium truncate',
            isCancelled && 'line-through opacity-60'
          )}
        >
          {event.title}
        </span>
        <span className="text-[11px] tabular-nums shrink-0 opacity-70">{startTime}</span>
      </div>
      {event.extendedProps.serviceName && (
        <span className="text-[10px] opacity-60 truncate">
          {event.extendedProps.serviceName}
        </span>
      )}

      {/* Status dot (bottom-left-ish area, shifts right when project icon present) */}
      {dotClass && (
        <span
          aria-hidden="true"
          className={cn(
            'absolute bottom-1 right-1 h-1.5 w-1.5 rounded-full',
            dotClass,
            projectId && 'right-4'
          )}
        />
      )}

      {/* Deposit dot — top-right corner */}
      {showDepositDot && (
        <span
          role="img"
          title={depositDotTitle}
          aria-label={depositDotTitle}
          className={cn(
            'deposit-dot',
            depositPaid ? 'paid' : 'unpaid'
          )}
        />
      )}

      {/* Project chain icon — bottom-right */}
      {projectId && (
        <button
          type="button"
          aria-label={
            projectName
              ? `Part of project: ${projectName}${sessionNumber != null ? ` · Session ${sessionNumber}` : ''}`
              : 'View project'
          }
          title={
            projectName
              ? `Part of project: ${projectName}${sessionNumber != null ? ` · Session ${sessionNumber}` : ''}`
              : 'View project'
          }
          onClick={(e) => {
            e.stopPropagation()
            router.push(`/projects/${projectId}`)
          }}
          className="project-icon"
        >
          <Link2 className="h-2.5 w-2.5" />
        </button>
      )}
    </div>
  )
}

'use client'

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { useQuery } from '@tanstack/react-query'
import { differenceInCalendarDays, parseISO, format } from 'date-fns'
import { Users, ChevronDown, ChevronUp, ExternalLink, CalendarDays, X } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import { Skeleton } from '@/components/ui/skeleton'
import { cn } from '@/lib/utils'
import { logger } from '@/lib/logger'

// ── Types ────────────────────────────────────────────────────────────────────

interface EngagementArtist {
  id: string
  display_name: string
  avatar_url: string | null
  portfolio_url?: string | null
}

interface GuestEngagement {
  id: string
  artist_id: string
  start_date: string  // YYYY-MM-DD
  end_date: string    // YYYY-MM-DD
  status: 'upcoming' | 'active' | 'completed' | 'cancelled'
  calendar_color: string | null
  contact_email: string | null
  agreement_notes: string | null
  artists: EngagementArtist | null
}

interface EngagementApiResponse {
  data: GuestEngagement[]
  count: number
}

interface GuestArtistStripProps {
  /** ISO string from FullCalendar datesSet activeStart */
  viewStart: string
  /** ISO string from FullCalendar datesSet activeEnd */
  viewEnd: string
}

// ── Constants ────────────────────────────────────────────────────────────────

const STORAGE_KEY = 'calendar-guest-strip-visible'
const ARTIST_COLORS = [
  'var(--color-artist-1)',
  'var(--color-artist-2)',
  'var(--color-artist-3)',
  'var(--color-artist-4)',
  'var(--color-artist-5)',
  'var(--color-artist-6)',
  'var(--color-artist-7)',
  'var(--color-artist-8)',
  'var(--color-artist-9)',
  'var(--color-artist-10)',
]

function getArtistColor(index: number): string {
  return ARTIST_COLORS[index % ARTIST_COLORS.length] ?? ARTIST_COLORS[0]!
}

function readStoredVisibility(): boolean {
  if (typeof window === 'undefined') return true
  try {
    const stored = localStorage.getItem(STORAGE_KEY)
    return stored === null ? true : stored !== 'false'
  } catch {
    return true
  }
}

// ── Engagement bar ────────────────────────────────────────────────────────────

interface EngagementBarProps {
  engagement: GuestEngagement
  colorIndex: number
  viewStartDate: Date
  totalDays: number
  onBookClick: (artistId: string) => void
}

function EngagementBar({
  engagement,
  colorIndex,
  viewStartDate,
  totalDays,
  onBookClick,
}: EngagementBarProps) {
  const [open, setOpen] = useState(false)
  const color = engagement.calendar_color ?? getArtistColor(colorIndex)
  const artist = engagement.artists

  // Calculate bar position as % of total view width
  const engStart = parseISO(engagement.start_date)
  const engEnd = parseISO(engagement.end_date)

  // Clamp to visible range
  const clampedStart = engStart < viewStartDate ? viewStartDate : engStart
  const totalViewEnd = new Date(viewStartDate)
  totalViewEnd.setDate(totalViewEnd.getDate() + totalDays)
  const clampedEnd = engEnd > totalViewEnd ? totalViewEnd : engEnd

  const offsetDays = differenceInCalendarDays(clampedStart, viewStartDate)
  const spanDays = differenceInCalendarDays(clampedEnd, clampedStart) + 1

  const leftPct = (offsetDays / totalDays) * 100
  const widthPct = (spanDays / totalDays) * 100

  const formattedStart = format(engStart, 'MMM d')
  const formattedEnd = format(engEnd, 'MMM d, yyyy')

  const initials = artist?.display_name
    .split(' ')
    .map((w) => w[0])
    .join('')
    .toUpperCase()
    .slice(0, 2)

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button
          type="button"
          aria-label={`Guest artist: ${artist?.display_name ?? 'Unknown'} — ${formattedStart} to ${formattedEnd}`}
          className="guest-artist-bar absolute top-0 bottom-0 flex items-center gap-1.5 px-2 text-[11px] font-medium truncate focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          style={{
            left: `${leftPct}%`,
            width: `${Math.max(widthPct, 4)}%`,
            background: `color-mix(in oklch, ${color} 18%, var(--color-muted))`,
            borderLeft: `3px solid ${color}`,
            color: color,
          }}
        >
          {/* Avatar / initials */}
          <span
            className="shrink-0 flex items-center justify-center h-4 w-4 rounded-full text-[8px] font-bold overflow-hidden"
            style={{ background: `color-mix(in oklch, ${color} 30%, var(--color-muted))` }}
          >
            {artist?.avatar_url ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img
                src={artist.avatar_url}
                alt={artist.display_name}
                className="h-full w-full object-cover"
              />
            ) : (
              <span style={{ color }}>{initials}</span>
            )}
          </span>
          <span className="truncate">{artist?.display_name ?? 'Guest Artist'}</span>
        </button>
      </PopoverTrigger>

      <PopoverContent
        className="w-72 p-0 overflow-hidden"
        side="bottom"
        align="start"
        sideOffset={4}
      >
        {/* Header strip */}
        <div
          className="px-4 py-3 flex items-start gap-3"
          style={{
            background: `color-mix(in oklch, ${color} 12%, var(--color-card))`,
            borderBottom: `1px solid color-mix(in oklch, ${color} 25%, var(--color-border))`,
          }}
        >
          <div
            className="shrink-0 flex items-center justify-center h-10 w-10 rounded-full text-sm font-bold overflow-hidden"
            style={{ background: `color-mix(in oklch, ${color} 25%, var(--color-muted))`, color }}
          >
            {artist?.avatar_url ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img
                src={artist.avatar_url}
                alt={artist?.display_name ?? 'Guest'}
                className="h-full w-full object-cover"
              />
            ) : (
              <span>{initials}</span>
            )}
          </div>
          <div className="flex-1 min-w-0">
            <p className="text-sm font-semibold truncate" style={{ color }}>
              {artist?.display_name ?? 'Guest Artist'}
            </p>
            <div className="flex items-center gap-1 mt-0.5 text-xs text-muted-foreground">
              <CalendarDays className="h-3 w-3 shrink-0" />
              <span>
                {formattedStart} — {formattedEnd}
              </span>
            </div>
          </div>
        </div>

        {/* Details */}
        <div className="px-4 py-3 space-y-2">
          {engagement.contact_email && (
            <p className="text-xs text-muted-foreground truncate">
              {engagement.contact_email}
            </p>
          )}
          {engagement.agreement_notes && (
            <p className="text-xs text-muted-foreground line-clamp-2">
              {engagement.agreement_notes}
            </p>
          )}
        </div>

        {/* Footer */}
        <div className="px-4 pb-3 flex gap-2">
          {artist?.portfolio_url && (
            <Button
              variant="outline"
              size="sm"
              className="h-7 text-xs gap-1"
              asChild
            >
              <a
                href={artist.portfolio_url}
                target="_blank"
                rel="noopener noreferrer"
              >
                <ExternalLink className="h-3 w-3" />
                Portfolio
              </a>
            </Button>
          )}
          <Button
            size="sm"
            className="h-7 text-xs flex-1"
            onClick={() => {
              setOpen(false)
              onBookClick(engagement.artist_id)
            }}
          >
            Book with guest
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  )
}

// ── Main strip component ──────────────────────────────────────────────────────

export function GuestArtistStrip({ viewStart, viewEnd }: GuestArtistStripProps) {
  const [visible, setVisible] = useState(readStoredVisibility)
  const containerRef = useRef<HTMLDivElement>(null)
  const [containerWidth, setContainerWidth] = useState(0)

  // Measure container to determine pixel layout (unused for % approach, but useful for min-width guard)
  useEffect(() => {
    const el = containerRef.current
    if (!el) return
    const ro = new ResizeObserver((entries) => {
      const entry = entries[0]
      if (entry) setContainerWidth(entry.contentRect.width)
    })
    ro.observe(el)
    return () => ro.disconnect()
  }, [])

  // Persist toggle
  const toggleVisible = useCallback(() => {
    setVisible((prev) => {
      const next = !prev
      try {
        localStorage.setItem(STORAGE_KEY, String(next))
      } catch {
        // localStorage unavailable
      }
      return next
    })
  }, [])

  // Compute date range for query
  const viewStartDate = useMemo(() => new Date(viewStart), [viewStart])
  const viewEndDate = useMemo(() => new Date(viewEnd), [viewEnd])
  const totalDays = useMemo(
    () => Math.max(1, differenceInCalendarDays(viewEndDate, viewStartDate)),
    [viewStartDate, viewEndDate]
  )

  const fromParam = format(viewStartDate, 'yyyy-MM-dd')
  const toParam = format(viewEndDate, 'yyyy-MM-dd')

  const { data, isLoading } = useQuery<GuestEngagement[]>({
    queryKey: ['guest-engagements-calendar', fromParam, toParam],
    queryFn: async () => {
      const res = await fetch(
        `/api/guest-artists/engagements?from=${fromParam}&to=${toParam}`
      )
      if (!res.ok) {
        logger.error({ status: res.status }, 'failed to fetch guest engagements for calendar')
        throw new Error('Failed to fetch guest engagements')
      }
      const json = await res.json() as EngagementApiResponse
      return (json.data ?? []).filter(
        (e) => e.status === 'active' || e.status === 'upcoming'
      )
    },
    staleTime: 60_000,
  })

  // Don't render if no engagements in view and not loading
  const engagements = data ?? []
  if (!isLoading && engagements.length === 0) return null

  // Placeholder "Book with guest" handler — opens booking drawer with artist pre-selected
  // The CalendarPageClient wires this via URL param pattern used elsewhere
  const handleBookClick = useCallback((artistId: string) => {
    // Navigate to new booking with artist pre-selected
    const url = new URL(window.location.href)
    url.searchParams.set('new_booking_artist', artistId)
    window.history.replaceState({}, '', url.toString())
    // Trigger booking drawer open (consumer can listen to searchParams)
    window.dispatchEvent(new CustomEvent('inkos:open-booking-drawer', { detail: { artistId } }))
  }, [])

  return (
    <div
      className={cn(
        'guest-artist-strip',
        !visible && 'guest-artist-strip--collapsed'
      )}
    >
      {/* Strip header / toggle row */}
      <div className="flex items-center justify-between gap-2 px-1">
        <button
          type="button"
          onClick={toggleVisible}
          className="flex items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground transition-colors"
          aria-expanded={visible}
          aria-label={visible ? 'Hide guest artist residencies' : 'Show guest artist residencies'}
        >
          <Users className="h-3 w-3 shrink-0" />
          <span className="font-medium">Guest Residencies</span>
          {visible ? (
            <ChevronUp className="h-3 w-3" />
          ) : (
            <ChevronDown className="h-3 w-3" />
          )}
          {!isLoading && engagements.length > 0 && (
            <span className="ml-1 rounded-full px-1.5 py-0 text-[10px] font-semibold bg-muted text-muted-foreground tabular-nums">
              {engagements.length}
            </span>
          )}
        </button>

        {visible && (
          <button
            type="button"
            className="text-muted-foreground hover:text-foreground transition-colors"
            aria-label="Close guest residency strip"
            onClick={toggleVisible}
          >
            <X className="h-3 w-3" />
          </button>
        )}
      </div>

      {/* Bars container */}
      {visible && (
        <div
          ref={containerRef}
          className="relative w-full"
          style={{ minHeight: isLoading ? '28px' : `${Math.max(engagements.length, 1) * 32}px` }}
          aria-label="Guest artist residency bars"
        >
          {isLoading && (
            <div className="space-y-1 px-1 pt-1">
              <Skeleton className="h-6 w-3/4 rounded" />
              <Skeleton className="h-6 w-1/2 rounded" />
            </div>
          )}

          {!isLoading && containerWidth > 0 &&
            engagements.map((engagement, idx) => (
              <div
                key={engagement.id}
                className="relative w-full"
                style={{ height: '28px', marginBottom: '4px' }}
              >
                <EngagementBar
                  engagement={engagement}
                  colorIndex={idx}
                  viewStartDate={viewStartDate}
                  totalDays={totalDays}
                  onBookClick={handleBookClick}
                />
              </div>
            ))
          }

          {/* Fallback render when containerWidth not yet measured */}
          {!isLoading && containerWidth === 0 &&
            engagements.map((engagement, idx) => (
              <div
                key={engagement.id}
                className="relative w-full"
                style={{ height: '28px', marginBottom: '4px' }}
              >
                <EngagementBar
                  engagement={engagement}
                  colorIndex={idx}
                  viewStartDate={viewStartDate}
                  totalDays={totalDays}
                  onBookClick={handleBookClick}
                />
              </div>
            ))
          }
        </div>
      )}
    </div>
  )
}

