'use client'

import { useRouter } from 'next/navigation'
import type { EventApi } from '@fullcalendar/core'
import { Link2 } from 'lucide-react'
import { cn } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type BookingStatus = Database['public']['Tables']['bookings']['Row']['status']

const STATUS_DOT_CLASSES: Partial<Record<BookingStatus, string>> = {
  in_progress: 'bg-[var(--color-status-in-progress)] animate-pulse',
  completed: 'bg-[var(--color-status-completed)]',
  cancelled: 'bg-[var(--color-status-cancelled)]',
  no_show: 'bg-[var(--color-status-no-show)]',
}

interface AppointmentCardProps {
  event: EventApi
}

export function AppointmentCard({ event }: AppointmentCardProps) {
  const router = useRouter()
  const status = event.extendedProps.status as BookingStatus
  const projectId = event.extendedProps.projectId as string | null | undefined
  const sessionNumber = event.extendedProps.sessionNumber as number | null | undefined
  const projectName = event.extendedProps.projectName as string | null | undefined
  const depositCents = event.extendedProps.depositCents as number
  const depositPaid = event.extendedProps.depositPaid as boolean

  const startTime = event.start
    ? event.start.toLocaleTimeString('en-US', {
        hour: 'numeric',
        minute: '2-digit',
        hour12: true,
      })
    : ''

  const dotClass = STATUS_DOT_CLASSES[status]
  const isCancelled = status === 'cancelled'

  // Deposit dot: only shown when deposit is required (cents > 0)
  const showDepositDot = depositCents > 0

  return (
    <div className="relative flex h-full flex-col overflow-hidden px-1.5 py-0.5">
      <div className="flex items-center justify-between gap-1">
        <span
          className={cn(
            'text-[11px] font-medium truncate',
            isCancelled && 'line-through opacity-60'
          )}
        >
          {event.title}
        </span>
        <span className="text-[11px] tabular-nums shrink-0 opacity-70">{startTime}</span>
      </div>
      {event.extendedProps.serviceName && (
        <span className="text-[10px] opacity-60 truncate">
          {event.extendedProps.serviceName}
        </span>
      )}

      {/* Status dot — shifts left when project icon present */}
      {dotClass && (
        <span
          aria-hidden="true"
          className={cn(
            'absolute bottom-1 right-1 h-1.5 w-1.5 rounded-full',
            dotClass,
            projectId && 'right-4'
          )}
        />
      )}

      {/* Deposit status dot — top-right corner */}
      {showDepositDot && (
        <span
          role="img"
          title={depositPaid ? 'Deposit paid' : 'Deposit pending'}
          aria-label={depositPaid ? 'Deposit paid' : 'Deposit pending'}
          className={cn('deposit-dot', depositPaid ? 'paid' : 'unpaid')}
        />
      )}

      {/* Project chain icon — bottom-right */}
      {projectId && (
        <button
          type="button"
          title={
            projectName
              ? `Part of project: ${projectName}${sessionNumber != null ? ` · Session ${sessionNumber}` : ''}`
              : 'View project'
          }
          aria-label={
            projectName
              ? `Part of project: ${projectName}${sessionNumber != null ? ` · Session ${sessionNumber}` : ''}`
              : 'View project'
          }
          onClick={(e) => {
            e.stopPropagation()
            router.push(`/projects/${projectId}`)
          }}
          className="project-icon"
        >
          <Link2 className="h-2.5 w-2.5" />
        </button>
      )}
    </div>
  )
}

'use client'

import { useRef, useEffect, useState, useMemo, useCallback, startTransition } from 'react'
import FullCalendar from '@fullcalendar/react'
import dayGridPlugin from '@fullcalendar/daygrid'
import timeGridPlugin from '@fullcalendar/timegrid'
import interactionPlugin from '@fullcalendar/interaction'
import listPlugin from '@fullcalendar/list'
import type {
  EventInput,
  EventDropArg,
  DateSelectArg,
  EventClickArg,
} from '@fullcalendar/core'
import type { DateClickArg } from '@fullcalendar/interaction'

interface EventResizeDoneArg {
  event: { id: string; start: Date | null; end: Date | null; extendedProps: Record<string, unknown> }
  revert: () => void
}
import { CalendarToolbar, type CalendarView as CalendarViewType } from './CalendarToolbar'
import { AppointmentCard } from './AppointmentCard'
import { CalendarFilterRow } from './CalendarFilterRow'
import { CalendarFab } from './CalendarFab'
import { GuestArtistStrip } from './GuestArtistStrip'
import { Skeleton } from '@/components/ui/skeleton'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Button } from '@/components/ui/button'
import { CalendarPlus, FilterX, AlertCircle } from 'lucide-react'
import { toast } from 'sonner'
import { logger } from '@/lib/logger'

const ARTIST_COLOR_CLASSES = [
  '',
  'artist-event-1',
  'artist-event-2',
  'artist-event-3',
  'artist-event-4',
  'artist-event-5',
  'artist-event-6',
  'artist-event-7',
  'artist-event-8',
  'artist-event-9',
  'artist-event-10',
]

function getArtistColorClass(sortOrder: number): string {
  const index = ((sortOrder - 1) % 10) + 1
  return ARTIST_COLOR_CLASSES[index] ?? 'artist-event-1'
}

export interface CalendarBooking {
  id: string
  scheduled_at: string
  end_at: string
  duration_min: number
  status: string
  client: { id: string; first_name: string; last_name: string | null }
  artist: { id: string; display_name: string; avatar_url: string | null; sort_order: number }
  service: { id: string; name: string; color: string | null } | null
  /** Deposit amount in cents — 0 means no deposit required */
  deposit_cents?: number | null
  deposit_paid?: boolean | null
  /** Project link — null when booking is standalone */
  project_id?: string | null
  session_number?: number | null
  /** Joined project name for tooltip */
  project?: { name: string } | null
}

interface CalendarViewProps {
  bookings: CalendarBooking[]
  isLoading: boolean
  error: string | null
  totalBookings: number
  filterArtistIds: string[]
  filterStatuses: string[]
  filterServiceIds: string[]
  onArtistFilterChange: (ids: string[]) => void
  onStatusFilterChange: (statuses: string[]) => void
  onServiceFilterChange: (ids: string[]) => void
  onNewAppointment: (start?: Date, end?: Date) => void
  onEditAppointment: (id: string) => void
  onReschedule: (id: string, newStart: Date, newEnd: Date) => Promise<void>
  onRetry: () => void
  studioId?: string
  /** Optional callback when FullCalendar changes the visible date range */
  onViewDatesChange?: (start: string, end: string) => void
}

// Minimum default slot duration when clicking an empty slot (30 min)
const DEFAULT_SLOT_DURATION_MS = 30 * 60 * 1000

// Mobile breakpoint — mirrors Tailwind md (768px)
const MOBILE_BREAKPOINT = 768

function getDefaultMobileView(): CalendarViewType {
  if (typeof window === 'undefined') return 'timeGridWeek'
  return window.innerWidth < MOBILE_BREAKPOINT ? 'listWeek' : 'timeGridWeek'
}

export function CalendarView({
  bookings,
  isLoading,
  error,
  totalBookings,
  filterArtistIds,
  filterStatuses,
  filterServiceIds,
  onArtistFilterChange,
  onStatusFilterChange,
  onServiceFilterChange,
  onNewAppointment,
  onEditAppointment,
  onReschedule,
  onRetry,
  studioId,
  onViewDatesChange,
}: CalendarViewProps) {
  const calendarRef = useRef<FullCalendar>(null)
  const containerRef = useRef<HTMLDivElement>(null)

  // Pointer tracking for mobile swipe (C6)
  const swipeStartX = useRef<number | null>(null)
  const swipeStartY = useRef<number | null>(null)

  const [view, setView] = useState<CalendarViewType>(() => {
    if (typeof window !== 'undefined') {
      try {
        const saved = localStorage.getItem('inkos-calendar-view')
        if (saved) return saved as CalendarViewType
      } catch {
        // localStorage unavailable (private mode, quota exceeded)
      }
    }
    return getDefaultMobileView()
  })
  const [title, setTitle] = useState('')

  // Derive range dates for iCal export and guest strip
  const [rangeStart, setRangeStart] = useState<string | undefined>()
  const [rangeEnd, setRangeEnd] = useState<string | undefined>()

  // Sync view to FullCalendar on change
  useEffect(() => {
    const api = calendarRef.current?.getApi()
    if (!api) return
    api.changeView(view)
    localStorage.setItem('inkos-calendar-view', view)
  }, [view])

  // Update title after navigation
  const updateTitle = useCallback(() => {
    const api = calendarRef.current?.getApi()
    if (!api) return
    const start = api.view.activeStart.toISOString()
    const end = api.view.activeEnd.toISOString()
    setTitle(api.view.title)
    setRangeStart(start)
    setRangeEnd(end)
    onViewDatesChange?.(start, end)
  }, [onViewDatesChange])

  useEffect(() => {
    const api = calendarRef.current?.getApi()
    if (api) {
      const start = api.view.activeStart.toISOString()
      const end = api.view.activeEnd.toISOString()
      startTransition(() => {
        setTitle(api.view.title)
        setRangeStart(start)
        setRangeEnd(end)
      })
      onViewDatesChange?.(start, end)
    }
    // Only run once on mount — onViewDatesChange excluded intentionally
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // ── C5: Keyboard shortcuts ──────────────────────────────────────────────
  useEffect(() => {
    function onKeyDown(e: KeyboardEvent) {
      // Ignore when typing in inputs/textareas/contenteditable
      const target = e.target as HTMLElement
      const tag = target.tagName
      if (tag === 'INPUT' || tag === 'TEXTAREA' || target.isContentEditable) return
      // Ignore modifier combos
      if (e.ctrlKey || e.metaKey || e.altKey) return

      const api = calendarRef.current?.getApi()
      if (!api) return

      switch (e.key) {
        case 't':
        case 'T':
          e.preventDefault()
          api.today()
          updateTitle()
          break
        case '[':
          e.preventDefault()
          api.prev()
          updateTitle()
          break
        case ']':
          e.preventDefault()
          api.next()
          updateTitle()
          break
        case 'd':
        case 'D':
          e.preventDefault()
          setView('timeGridDay')
          break
        case 'w':
        case 'W':
          e.preventDefault()
          setView('timeGridWeek')
          break
        case 'm':
        case 'M':
          e.preventDefault()
          setView('dayGridMonth')
          break
        case 'a':
        case 'A':
          e.preventDefault()
          setView('listWeek')
          break
        case 'n':
        case 'N':
          e.preventDefault()
          onNewAppointment()
          break
        case 'Escape':
          // Propagates naturally; no override needed here
          break
        default:
          break
      }
    }

    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [onNewAppointment, updateTitle])

  // ── C6: Mobile swipe gesture ────────────────────────────────────────────
  useEffect(() => {
    const el = containerRef.current
    if (!el) return

    function onPointerDown(e: PointerEvent) {
      swipeStartX.current = e.clientX
      swipeStartY.current = e.clientY
    }

    function onPointerUp(e: PointerEvent) {
      if (swipeStartX.current === null || swipeStartY.current === null) return
      const dx = e.clientX - swipeStartX.current
      const dy = e.clientY - swipeStartY.current
      swipeStartX.current = null
      swipeStartY.current = null

      // Only horizontal swipes (dx > 50, horizontal dominates)
      if (Math.abs(dx) < 50 || Math.abs(dy) > Math.abs(dx)) return

      const api = calendarRef.current?.getApi()
      if (!api) return

      if (dx < 0) {
        api.next()
      } else {
        api.prev()
      }
      updateTitle()
    }

    el.addEventListener('pointerdown', onPointerDown)
    el.addEventListener('pointerup', onPointerUp)
    return () => {
      el.removeEventListener('pointerdown', onPointerDown)
      el.removeEventListener('pointerup', onPointerUp)
    }
  }, [updateTitle])

  const events: EventInput[] = useMemo(() => {
    return bookings
      .filter((b) => {
        if (filterArtistIds.length > 0 && !filterArtistIds.includes(b.artist.id)) return false
        if (filterStatuses.length > 0 && !filterStatuses.includes(b.status)) return false
        if (filterServiceIds.length > 0 && (b.service === null || !filterServiceIds.includes(b.service.id))) return false
        return true
      })
      .map((b) => ({
        id: b.id,
        title: `${b.client.first_name} ${b.client.last_name ?? ''}`.trim(),
        start: b.scheduled_at,
        end: b.end_at,
        classNames: [
          getArtistColorClass(b.artist.sort_order),
          `status-${b.status}`,
        ],
        extendedProps: {
          appointmentId: b.id,
          artistId: b.artist.id,
          status: b.status,
          serviceName: b.service?.name ?? null,
          projectId: b.project_id ?? null,
          sessionNumber: b.session_number ?? null,
          projectName: b.project?.name ?? null,
          depositCents: b.deposit_cents ?? 0,
          depositPaid: b.deposit_paid ?? false,
        },
      }))
  }, [bookings, filterArtistIds, filterStatuses, filterServiceIds])

  const artists = useMemo(() => {
    const seen = new Set<string>()
    return bookings
      .filter((b) => {
        if (seen.has(b.artist.id)) return false
        seen.add(b.artist.id)
        return true
      })
      .map((b) => ({
        id: b.artist.id,
        display_name: b.artist.display_name,
        sort_order: b.artist.sort_order,
        colorClass: getArtistColorClass(b.artist.sort_order),
      }))
  }, [bookings])

  const services = useMemo(() => {
    const seen = new Set<string>()
    return bookings
      .filter((b) => {
        if (!b.service) return false
        if (seen.has(b.service.id)) return false
        seen.add(b.service.id)
        return true
      })
      .map((b) => ({
        id: b.service!.id,
        name: b.service!.name,
      }))
  }, [bookings])

  // ── C3: Drag-to-reschedule with optimistic rollback + undo ──────────────
  const handleEventDrop = useCallback(
    async (info: EventDropArg) => {
      const { event, revert } = info
      if (!event.start || !event.end) return

      // Capture pre-drop state for undo
      const originalStart = new Date(event.start.getTime() - (info.delta?.milliseconds ?? 0))
      const originalEnd = new Date(event.end.getTime() - (info.delta?.milliseconds ?? 0))
      const appointmentId = event.id

      let undoUsed = false

      // Show optimistic undo toast
      toast.success('Appointment rescheduled', {
        action: {
          label: 'Undo',
          onClick: () => {
            undoUsed = true
            revert()
            // Fire API call to restore original times
            onReschedule(appointmentId, originalStart, originalEnd).catch((err) => {
              logger.error({ err }, 'undo reschedule failed')
              toast.error('Failed to undo reschedule')
            })
          },
        },
        duration: 6000,
      })

      try {
        await onReschedule(appointmentId, event.start, event.end)
      } catch (err) {
        if (undoUsed) return // Undo already in flight, ignore
        const message = err instanceof Error ? err.message : 'Reschedule failed'
        if (message.includes('time_slot_unavailable') || message.includes('23P01')) {
          toast.error('That time slot is already booked')
        } else {
          toast.error('Failed to reschedule appointment')
        }
        revert()
        logger.error({ err }, 'calendar event drop failed')
      }
    },
    [onReschedule]
  )

  const handleEventResize = useCallback(
    async (info: EventResizeDoneArg) => {
      const { event, revert } = info
      if (!event.start || !event.end) return

      try {
        await onReschedule(event.id, event.start, event.end)
        toast.success('Appointment duration updated')
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Resize failed'
        if (message.includes('time_slot_unavailable') || message.includes('23P01')) {
          toast.error('That time slot is already booked')
        } else {
          toast.error('Failed to update appointment duration')
        }
        revert()
        logger.error({ err }, 'calendar event resize failed')
      }
    },
    [onReschedule]
  )

  const handleSelect = useCallback(
    (info: DateSelectArg) => {
      onNewAppointment(info.start, info.end)
    },
    [onNewAppointment]
  )

  // ── C4: Click-empty-slot → quick-add (dateClick) ────────────────────────
  const handleDateClick = useCallback(
    (info: DateClickArg) => {
      const start = info.date
      const end = new Date(start.getTime() + DEFAULT_SLOT_DURATION_MS)
      onNewAppointment(start, end)
    },
    [onNewAppointment]
  )

  const handleEventClick = useCallback(
    (info: EventClickArg) => {
      onEditAppointment(info.event.extendedProps.appointmentId as string)
    },
    [onEditAppointment]
  )

  const filteredCount = events.length
  const isEmpty = !isLoading && filteredCount === 0

  return (
    <div className="flex flex-col flex-1 overflow-hidden" ref={containerRef}>
      <CalendarToolbar
        view={view}
        title={title}
        {...(studioId !== undefined ? { studioId } : {})}
        {...(rangeStart !== undefined ? { rangeStart } : {})}
        {...(rangeEnd !== undefined ? { rangeEnd } : {})}
        onViewChange={setView}
        onPrev={() => {
          calendarRef.current?.getApi().prev()
          updateTitle()
        }}
        onNext={() => {
          calendarRef.current?.getApi().next()
          updateTitle()
        }}
        onToday={() => {
          calendarRef.current?.getApi().today()
          updateTitle()
        }}
        onNewAppointment={() => onNewAppointment()}
      />

      <CalendarFilterRow
        artists={artists}
        services={services}
        filterArtistIds={filterArtistIds}
        filterStatuses={filterStatuses}
        filterServiceIds={filterServiceIds}
        onArtistFilterChange={onArtistFilterChange}
        onStatusFilterChange={onStatusFilterChange}
        onServiceFilterChange={onServiceFilterChange}
      />

      {/* B1: Guest artist residency strip — shown when view range is known */}
      {rangeStart && rangeEnd && (
        <GuestArtistStrip viewStart={rangeStart} viewEnd={rangeEnd} />
      )}

      {/* Keyboard shortcut hint bar (desktop only) */}
      <div className="calendar-shortcuts-bar hidden sm:flex">
        {[
          { key: 'T', label: 'Today' },
          { key: '[', label: 'Prev' },
          { key: ']', label: 'Next' },
          { key: 'D', label: 'Day' },
          { key: 'W', label: 'Week' },
          { key: 'M', label: 'Month' },
          { key: 'A', label: 'Agenda' },
          { key: 'N', label: 'New' },
        ].map(({ key, label }) => (
          <span key={key} className="inline-flex items-center gap-1">
            <kbd className="calendar-shortcut-key">{key}</kbd>
            <span>{label}</span>
          </span>
        ))}
      </div>

      {error && (
        <div className="px-4 py-2">
          <Alert variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription className="flex items-center justify-between">
              Couldn&apos;t load appointments
              <Button
                variant="outline"
                size="sm"
                className="ml-3 h-6 text-xs"
                onClick={onRetry}
              >
                Retry
              </Button>
            </AlertDescription>
          </Alert>
        </div>
      )}

      {isLoading && (
        <div className="flex-1 overflow-hidden px-4 pb-4 pt-2">
          <div className="space-y-2">
            <Skeleton className="h-16 w-3/4 rounded-md" />
            <Skeleton className="h-12 w-1/2 rounded-md" />
            <Skeleton className="h-20 w-2/3 rounded-md" />
          </div>
        </div>
      )}

      {!isLoading && isEmpty && totalBookings === 0 && (
        <div className="flex flex-1 flex-col items-center justify-center gap-4 px-4 pb-4">
          <div className="rounded-xl bg-primary/10 p-4">
            <CalendarPlus className="h-12 w-12 text-primary/70" />
          </div>
          <div className="text-center space-y-1">
            <h3 className="text-base font-medium">Your first booking will appear here</h3>
            <p className="text-sm text-muted-foreground">
              Share your booking link to get started
            </p>
          </div>
          <div className="flex gap-2">
            <Button size="sm" onClick={() => onNewAppointment()}>
              <CalendarPlus className="mr-2 h-4 w-4" />
              New booking
            </Button>
          </div>
        </div>
      )}

      {!isLoading && isEmpty && totalBookings > 0 && (
        <div className="flex flex-1 flex-col items-center justify-center gap-4 px-4 pb-4">
          <div className="rounded-xl bg-primary/10 p-4">
            <FilterX className="h-10 w-10 text-primary/70" />
          </div>
          <div className="text-center space-y-1">
            <h3 className="text-base font-medium">No appointments match these filters</h3>
            <p className="text-sm text-muted-foreground">
              Try a different artist, date, or status
            </p>
          </div>
          <Button
            variant="outline"
            size="sm"
            onClick={() => {
              onArtistFilterChange([])
              onStatusFilterChange([])
              onServiceFilterChange([])
            }}
          >
            Clear filters
          </Button>
        </div>
      )}

      {!isLoading && !isEmpty && (
        <div className="flex-1 overflow-hidden px-4 pb-4">
          <div className="h-full rounded-xl border border-border/40 overflow-hidden shadow-[var(--shadow-glow-card,var(--shadow-card))]">
          <FullCalendar
            ref={calendarRef}
            plugins={[dayGridPlugin, timeGridPlugin, interactionPlugin, listPlugin]}
            initialView={view}
            headerToolbar={false}
            editable={true}
            droppable={false}
            selectable={true}
            selectMirror={true}
            nowIndicator={true}
            allDaySlot={false}
            slotDuration="00:30:00"
            slotMinTime="08:00:00"
            slotMaxTime="22:00:00"
            expandRows={true}
            stickyHeaderDates={true}
            dayMaxEvents={3}
            businessHours={{
              daysOfWeek: [1, 2, 3, 4, 5, 6],
              startTime: '10:00',
              endTime: '20:00',
            }}
            eventOverlap={(stillEvent, movingEvent) => {
              return (
                stillEvent.extendedProps.artistId !==
                movingEvent?.extendedProps.artistId
              )
            }}
            events={events}
            eventContent={(arg) => <AppointmentCard event={arg.event} />}
            select={handleSelect}
            dateClick={handleDateClick}
            eventClick={handleEventClick}
            eventDrop={handleEventDrop}
            eventResize={handleEventResize}
            height="100%"
            datesSet={updateTitle}
          />
          </div>
        </div>
      )}

      {/* C6: Mobile FAB */}
      <CalendarFab onClick={() => onNewAppointment()} />
    </div>
  )
}

