.artist-event-10 { border-left-color: var(--color-artist-10); background: var(--color-artist-10-surface); color: var(--color-artist-10); }

/* ──────────────────────────────────────────────────────────
   CALENDAR B1 — Deposit status dot (Sprint 13 Track B)
────────────────────────────────────────────────────────── */
.fc-event .deposit-dot {
  position: absolute;
  top: 4px;
  right: 4px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  /* knockout ring so dot is visible on any artist color surface */
  box-shadow: 0 0 0 1.5px var(--color-card);
  z-index: 2;
  pointer-events: none;
}
.fc-event .deposit-dot.paid {
  background: var(--color-success);
}
.fc-event .deposit-dot.unpaid {
  background: var(--color-destructive);
  animation: deposit-pulse 2s ease-in-out infinite;
}
@keyframes deposit-pulse {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0.55; }
}

/* ──────────────────────────────────────────────────────────
   CALENDAR B1 — Project chain icon (Sprint 13 Track B)
────────────────────────────────────────────────────────── */
.fc-event .project-icon {
  position: absolute;
  bottom: 2px;
  right: 2px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2px;
  border-radius: 3px;
  opacity: 0.65;
  z-index: 2;
  cursor: pointer;
  color: currentColor;
  background: transparent;
  border: none;
  transition: opacity 100ms ease-out;
}
.fc-event .project-icon:hover {
  opacity: 1;
  background: color-mix(in oklch, currentColor 12%, transparent);
}

/* ──────────────────────────────────────────────────────────
   CALENDAR B1 — Guest artist residency strip (Sprint 13 Track B)
────────────────────────────────────────────────────────── */
.guest-artist-strip {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 6px 16px 8px;
  background: var(--color-muted);
  border-bottom: 1px solid var(--color-border);
}
.guest-artist-strip--collapsed {
  padding-bottom: 6px;
}
.guest-artist-bar {
  position: absolute;
  top: 0;
  bottom: 0;
  border-radius: 6px;
  font-size: 11px;
  white-space: nowrap;
  overflow: hidden;
  transition: opacity 100ms ease-out, filter 100ms ease-out;
}
.guest-artist-bar:hover {
  opacity: 0.9;
  filter: brightness(1.08);
}

